<?php

/**
 * Default settings for the Static Maps API.
 *
 * DO NOT EDIT THIS FILE to change settings on your install: it is part of the
 * code and will be overwritten when you update. Instead, copy
 * `data/config.example.php` to `data/config.php` and put only the settings you
 * want to change there. Your file is merged over this one:
 *
 * - Settings that are arrays with named keys (such as `defaults`, `zoom`,
 *   `providers`, each provider and each style) are merged key by key, so you
 *   only list the keys you change.
 * - Everything else, including lists such as a style's `layers`, is replaced
 *   as a whole.
 *
 * A different install file can be used by setting the STATIC_MAPS_CONFIG
 * environment variable to its full path (for example in the PHP-FPM pool
 * configuration, or in tests).
 *
 * @see data/config.example.php
 */

return [

    /*
     * Values used when a request does not specify them.
     */
    'defaults' => [
        // Image width and height in pixels when the request has no `width` / `height`.
        // Default: 300 x 300.
        // Example override: 'defaults' => ['width' => 600, 'height' => 400],
        'width'        => 300,
        'height'       => 300,

        // Path line colour (hex RGB without '#') and weight (pixels) when a
        // `path[]` or `polyline` does not set `color:` / `weight:`.
        // Default: '333333' and 3.
        'path_color'   => '333333',
        'path_weight'  => 3,

        // Space in pixels kept around markers and paths when the map is fitted
        // to them (no `zoom` given), when the request has no `padding`: one
        // number, or 2-4 comma-separated in CSS order (top, right, bottom, left).
        // Marker icon sizes and path widths are always added on top.
        // Default: 20. Example override: 'padding' => '40,20'.
        'padding'      => 20,

        // Output format when the request has no `format`: 'png', 'png8' (256
        // colours, smaller), 'jpg' or 'webp' (if PHP's GD has WebP support;
        // otherwise maps are sent as PNG).
        // Default: 'png'.
        'format'       => 'png',

        // JPEG and WebP quality (1-100) when the request has no `quality`.
        // Default: 75.
        'jpeg_quality' => 75,

        // Map used when the request names no provider or style (or an unknown,
        // disabled or token-only one): a provider id from `providers` below and
        // one of its style ids. Must be enabled and must not need a token.
        // Default: 'osm' / 'streets'.
        // Example override: 'defaults' => ['provider' => 'carto', 'style' => 'light'],
        // (The old setting 'basemap' => '<old id>' still works but is deprecated.)
        'provider'     => 'osm',
        'style'        => 'streets',

        // Attribution drawn when the request has no `attribution` and the
        // provider or style has no `attribution` of its own. Every shipped
        // provider sets its own, so this only applies to providers you add
        // (and custom tile URLs). One of 'text', 'osm', 'esri', 'mapbox',
        // 'mapbox-small' or 'none'.
        // Default: 'osm'.
        'attribution'  => 'osm',
    ],

    /*
     * Largest image a request may ask for, in pixels. A larger `width` or
     * `height` is drawn at the limit instead, and the response says so in an
     * `X-Map-Size` header. Bigger images download more tiles from the tile
     * providers (a 1280x1280 map needs up to about 36 tiles per layer).
     * Default: 1280 x 1280.
     * 'max_markers' Most markers drawn on one map; later ones are left out, with
     *               an `X-Map-Limit` header. Each marker can mean an icon download.
     *               Default: 100.
     * 'max_points'  Most points in all of a map's paths together; a path that
     *               would go over is left out, with an `X-Map-Limit` header.
     *               Default: 10000.
     *
     * 'icon_urls'   Most different marker icon URLs per map (only clients with
     *               a key may use them); markers with more are left out with an
     *               `X-Marker-<n>` header. Default: 5.
     * 'icon_bytes'  Largest marker icon download, in bytes. Default: 262144 (256 KB).
     * 'icon_pixels' Marker icons from URLs larger than this many pixels wide or
     *               high are drawn at this size. Default: 256.
     * 'max_body_bytes' Largest JSON request body (POST with Content-Type:
     *               application/json, #38), in bytes; a larger one gets 413.
     *               Default: 1048576 (1 MB).
     * 'max_overlays' Most `overlay` layers on one map (#30); more are left out, with
     *               an `X-Map-Overlay` header. Each one downloads its own tiles.
     *               Default: 3.
     *
     * Example override: 'limits' => ['max_width' => 2048, 'max_height' => 2048, 'max_markers' => 20],
     */
    'limits' => [
        'max_width'   => 1280,
        'max_height'  => 1280,
        'max_markers' => 100,
        'max_points'  => 10000,
        'icon_urls'   => 5,
        'icon_bytes'  => 262144,
        'icon_pixels' => 256,
        'max_overlays' => 3,
        'max_body_bytes' => 1048576,
    ],

    /*
     * How the renderer treats markers and paths it can't draw (bad coordinates,
     * an unknown icon, unreadable points).
     *
     * 'strict' false (default): leave them out and say why in an `X-Marker-<n>`
     *          or `X-Path-<n>` header, so the rest of the map is still drawn.
     *          true: answer 400 with the reason instead.
     *
     * Example override: 'errors' => ['strict' => true],
     */
    'errors' => [
        'strict' => false,
    ],

    /*
     * Caching.
     *
     * 'max_age'          How long browsers, CDNs and proxies may keep a map
     *                    image, in seconds (sent as Cache-Control). The same
     *                    request draws the same image until the tiles change.
     *                    Default: 604800 (7 days).
     * 'fallback_max_age' Lifetime for a map drawn instead of the requested one
     *                    (X-Map-Fallback), which may become available later.
     *                    Default: 300 (5 minutes).
     *
     * Maps drawn for a request with a valid token, and maps from providers with
     * `cache => 'off'`, are marked private: browsers may keep them, shared
     * caches should not. Errors are not cached.
     *
     * 'tiles'            The cache of downloaded tiles on disk, shared by all
     *                    maps of the same area:
     *   'enabled'        On by default. If the directory can't be created or
     *                    written, maps are drawn without the cache and the
     *                    problem is logged.
     *   'dir'            Where tiles are kept. Default: data/cache/tiles.
     *   'max_size'       Most bytes the cache should use. Default: 1000000000
     *                    (1 GB, roughly 40,000-60,000 tiles). Enforced only by
     *                    bin/prune-cache.php, which you run from cron or a
     *                    systemd timer (see the README); without it the cache
     *                    keeps growing. 0 = no size limit.
     *   'default_ttl'    Seconds to keep a tile when its provider sends no
     *                    Cache-Control or Expires header. Default: 604800 (7 days,
     *                    as OpenStreetMap's tile policy asks). Otherwise the
     *                    provider's headers decide.
     *   'stale_if_error' Seconds after expiry that a cached tile may still be
     *                    drawn when the provider fails, unless the provider
     *                    sends its own stale-if-error. Default: 604800 (7 days).
     *
     * Providers with `cache => 'off'` never use the tile cache.
     *
     * Example overrides: 'cache' => ['max_age' => 86400],
     *                    'cache' => ['tiles' => ['max_size' => 5000000000]],
     *                    'cache' => ['tiles' => ['enabled' => false]],
     */
    'cache' => [
        'max_age'          => 604800,
        'fallback_max_age' => 300,
        'tiles'            => [
            'enabled'        => true,
            'dir'            => __DIR__ . '/../data/cache/tiles',
            'max_size'       => 1000000000,
            'default_ttl'    => 604800,
            'stale_if_error' => 604800,
        ],
    ],

    /*
     * Limits on every download from another server: tiles, icon URLs and
     * attribution image URLs. Only http and https are allowed.
     *
     * 'timeout'         Seconds a download may take in total. Default: 10.
     * 'connect_timeout' Seconds to wait for the server to answer. Default: 5.
     * 'max_bytes'       Largest download accepted, in bytes. Default: 5000000.
     * 'max_redirects'   Most redirects followed. Default: 3.
     *
     * Example override: 'remote' => ['timeout' => 5],
     */
    'remote' => [
        'timeout'         => 10,
        'connect_timeout' => 5,
        'max_bytes'       => 5000000,
        'max_redirects'   => 3,
    ],

    /*
     * Zoom range. Requested or automatically chosen zoom levels outside a map's
     * range are clamped to it.
     *
     * 'min' / 'max'  The range for providers and styles that don't set their
     *                own `minzoom` / `maxzoom`. A provider or style that sets
     *                its own uses that instead, even if it is wider.
     *                Default: 2 to 18.
     * 'max_limit'    Optional cap on every map: when set, no provider or style
     *                goes above it, whatever its own `maxzoom`. Use it to limit
     *                how many tiles high-zoom maps download. Not set (null) by
     *                default.
     *
     * Example overrides: 'zoom' => ['max' => 17],
     *                    'zoom' => ['max_limit' => 17],
     */
    'zoom' => [
        'min'       => 2,
        'max'       => 18,
        'max_limit' => null,
    ],

    /*
     * User-Agent header sent when downloading tiles. Tile providers such as
